package com.example.orchestration.workflow;import com.example.orchestration.event.LifecycleEvent;import org.springframework.beans.factory.annotation.Value;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import java.time.Instant;import java.util.*;@Component public class OrderActivitiesImpl implements OrderActivities{private final RestClient http=RestClient.create();private final KafkaTemplate<String,Object> kafka;private final String payment,network,fulfillment,billing;public OrderActivitiesImpl(KafkaTemplate<String,Object>k,@Value("${services.payment-url}")String p,@Value("${services.network-url}")String n,@Value("${services.fulfillment-url}")String f,@Value("${services.billing-url}")String b){kafka=k;payment=p;network=n;fulfillment=f;billing=b;}public void publish(OrderWorkflowRequest r,String type,String status){kafka.send("order-lifecycle-events",r.orderId(),new LifecycleEvent(UUID.randomUUID().toString(),r.orderId(),r.customerId(),type,status,Instant.now())).join();}public void pay(OrderWorkflowRequest r){post(payment+"/api/payments",Map.of("orderId",r.orderId(),"customerId",r.customerId(),"amount",r.total(),"currency","EUR","paymentMethod","SIMULATED_CARD","paymentToken","success"),Map.class);}public String activate(OrderWorkflowRequest r){return String.valueOf(post(network+"/api/activations",Map.of("orderId",r.orderId(),"customerId",r.customerId(),"planId",r.planId()),Map.class).get("id"));}public String fulfill(OrderWorkflowRequest r){return String.valueOf(post(fulfillment+"/api/fulfillments",Map.of("orderId",r.orderId(),"customerId",r.customerId(),"productId",r.productId()),Map.class).get("id"));}public String activationStatus(String id){return status(network+"/api/activations?orderId="+id);}public String fulfillmentStatus(String id){return status(fulfillment+"/api/fulfillments?orderId="+id);}public void startBilling(OrderWorkflowRequest r,String a,String f){post(billing+"/api/subscriptions",Map.of("orderId",r.orderId(),"customerId",r.customerId(),"planName",r.planName(),"monthlyAmount",r.monthlyAmount(),"activationId",a,"fulfillmentId",f),Map.class);}private String status(String u){return String.valueOf(http.get().uri(u).retrieve().body(Map.class).get("status"));}private<T>T post(String u,Object body,Class<T>type){return http.post().uri(u).body(body).retrieve().body(type);}}
